std::vector<std::string> names = {"A", "B", "C"};
int scores[] = {10, 20, 30};

// 1. By value (copy/read-only)
for (std::string s : names) { /* Use s */ }

// 2. By const reference (efficient read)
for (const auto& s : names) { /* Use s */ }

// 3. By reference (modification of elements)
for (auto& score : scores) { score *= 2; }

// 4. Over temporary initializer list
for (int i : {1, 2, 3}) { /* Use i */ }

// Note: Requires .begin() and .end()
// or range-based support (C++20)
